with base as (select *, round(amount * 1.07, 2) as adjusted_amount, coalesce(channel, 'DIRECT') as channel_clean from orders where order_date > to_date('2023-07-14') and channel is distinct from 'store') select id, order_date, channel, amount, shipping_fee, adjusted_amount, channel_clean, avg(adjusted_amount) over (order by adjusted_amount, id rows between 2 preceding and 1 preceding) as adjusted_amount_avg_2_prior, corr(discount, amount) over (partition by status) as corr_discount_amount from base;
